using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool(Name = "fetch_post", ReadOnly = true)]
    [Description("Fetches a post by ID from the JSONPlaceholder API.")]
    public static async Task<string> FetchPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric ID of the post to fetch (1-100).")] int postId,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var post = await client.GetFromJsonAsync<JsonElement>(
            $"/posts/{postId}", cancellationToken);

        return post.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

public sealed class SummarizationPrompts
{
    [McpServerPrompt(Name = "summarize")]
    [Description("Creates a prompt that asks the model to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Desired summary style: 'brief', 'detailed', or 'bullets'.")] string style = "brief")
    {
        var systemInstruction = style switch
        {
            "detailed" => "Provide a thorough, multi-paragraph summary of the following text.",
            "bullets"  => "Summarize the following text as a concise bullet-point list.",
            _          => "Provide a one-paragraph summary of the following text."
        };

        return
        [
            new()
            {
                Role = Role.User,
                Content = new TextContentBlock { Text = $"{systemInstruction}\n\n{text}" }
            }
        ];
    }
}

